def load_ngl_site_index(task, data_dir, filename):
    """Load available location attributes by NGL station code."""
    folder = Path(data_dir)

    matches = [path for path in folder.iterdir() if path.is_file() and path.name.casefold() == filename.casefold()]

    if len(matches) != 1:
        raise ValueError(f"Expected one reference catalog named {filename}")

    site_index = {}

    with matches[0].open(
        "r",
        encoding="utf-8-sig",
        newline="",
    ) as stream:
        reader = csv.DictReader(stream)

        required = {"CODE","CITY","REGION","COUNTRY",}

        if not required.issubset(reader.fieldnames or []):
            raise ValueError("The NGL reference catalog has incompatible headers")

        for number, row in enumerate(reader, 1):
            if number % 500 == 0 and task.isCanceled():
                return None

            station_id = (
                row.get("CODE") or ""
            ).strip().upper()

            if not station_id:
                continue

            attributes = {
                name: (row.get(name) or "").strip()
                for name in (
                    "CITY",
                    "REGION",
                    "COUNTRY",
                )
            }

            site_text = "/".join(
                attributes[name]
                for name in (
                    "CITY",
                    "REGION",
                    "COUNTRY",
                )
                if attributes[name]
            )

            if not site_text:
                continue

            attributes["SITE"] = site_text

            if station_id in site_index:
                previous = site_index[station_id]

                if previous is None:
                    continue

                previous_values = tuple(
                    previous[name].casefold()
                    for name in (
                        "CITY",
                        "REGION",
                        "COUNTRY",
                    )
                )

                current_values = tuple(
                    attributes[name].casefold()
                    for name in (
                        "CITY",
                        "REGION",
                        "COUNTRY",
                    )
                )

                if previous_values != current_values:
                    # Do not select between conflicting duplicate codes.
                    site_index[station_id] = None

            else:
                site_index[station_id] = attributes

    if task.isCanceled():
        return None

    return site_index


