    # Function for reinitialize. 
    def rest(self, checked=False):
        """Reset the plugin to its initial input state."""
        self._reset_session()

    # Function for preview file. 
    def load_header(self):
        global df, list_col, lin_def

        # Reset validation results whenever the selection is processed.
        self.clear_tx()

        pos_header=self.sl_header.currentIndex()
        
        file_ts=self.load_file.filePath()
        with open(file_ts, 'r') as _filehandler:
            lista=list()

            for row in _filehandler:
                lista.append(row)

        data=list()
        data_orig=list()
        cont_desc=""
        
        for x in range(0,len(lista)):
            if x>=pos_header:
                contenido = lista[x].split()
                data_orig.append(contenido)
            else:
                cont_desc+=lista[x]

        self.tx_descrip.setText(cont_desc)

        try:
            list_col=list()
            list_col.clear()

            if self.cb_header.isChecked():
                list_col=data_orig[0]

            else:
                for i in range(len(data_orig[0])):
                    nom_col='Col'+str(i+1)
                    list_col.append(nom_col)

            lin_def=0
            first_data_index = 1 if self.cb_header.isChecked() else 0

            for x in range(first_data_index,len(data_orig)):
                if len(list_col)==len(data_orig[x]):
                    data.append(data_orig[x])
                else:
                    lin_def+=1

            df = pd.DataFrame(data,columns=[list_col])

            self.Tab_start.clear()
            self.Tab_start.setRowCount(5)
            self.Tab_start.setColumnCount(len(list(df.columns.values)))

            col=0
            for i in list_col:
                self.Tab_start.setHorizontalHeaderItem(col, QTableWidgetItem(str(i)))
                col+=1

            num_data=len(df)
            if num_data>5:
                num_data=5

            for i in range(0,num_data):
                col=0
                for j in list(df.columns.values):
                    val=QTableWidgetItem(str(df.iloc[i][j]))
                    self.Tab_start.setItem((i),col,val)
                    col+=1

            # Option the X,Y,Y tiles
            self.loc_cors.setEnabled(True)
            self.mapbase.setEnabled(True)
            self.lat.setEnabled(True)
            self.longi.setEnabled(True)

            self.lat.clear()
            self.longi.clear()
            self.lat.addItem('')
            self.longi.addItem('')
            self.lat.addItems(list_col)
            self.longi.addItems(list_col)

        except ValueError:
            self.tx_descrip.setText("Select other end header")


    # Function for active bottom uploaddata
    def act_up_data(self):
        if self.lat.currentText()!="" and self.longi.currentText()!="":
                self.up_data.setEnabled(True)


    # Function for create vector layer with data lat and long of the file
    def up_canvas(self):
        op_lat = self.lat.currentText()
        op_long = self.longi.currentText()

        # Define type of geometry (point) and CRS
        geom_type = QgsWkbTypes.Point
        crs = "EPSG:4326"  # CRS WGS 84

        # Create the temporal layer
        uri = "Point?crs=" + crs
        layer = QgsVectorLayer(
            uri, self._local_station_layer_name(), "memory"
        )

        # Define fields of the attrib's tables 
        if Qgis.versionInt() >= 33800:
            fields = [
                QgsField("Date", QMetaType.Type.QString),
                QgsField("Lat", QMetaType.Type.Double),
                QgsField("Long", QMetaType.Type.Double),
            ]
        else:
            fields = [
                QgsField("Date", QVariant.String),
                QgsField("Lat", QVariant.Double),
                QgsField("Long", QVariant.Double),
            ]

        layer.dataProvider().addAttributes(fields)
        layer.updateFields()

        # Enable edit
        layer.startEditing()

        # Add point of list
        for i in range(len(df)):
            feature1 = QgsFeature()
            pos_1=list_col[0]
            C_F=str(df.iloc[i][pos_1])
            C_N=float(df.iloc[i][op_lat])
            C_E=float(df.iloc[i][op_long])
            if C_E>180:
                C_E=C_E-360
            feature1.setGeometry(QgsGeometry.fromPointXY(QgsPointXY(C_E,C_N)))
            feature1.setAttributes([C_F,C_N,C_E])
            layer.addFeature(feature1)

        # Save the change
        layer.commitChanges()

        # Generates point symbols in vectors.
        ruta_estilo = os.path.join(os.path.dirname(__file__), 'scripts', 'point.qml') 
        processing.run("native:setlayerstyle", {'INPUT':layer,'STYLE':ruta_estilo})

        # Add layer to the project
        QgsProject.instance().addMapLayer(layer)

        # Bind the published positions to the current local document.
        self._local_analysis_anchor = {
            "frame": weakref.ref(df),
            "path": self.load_file.filePath(),
            "count": len(df),
            "mode": "observations",
            "mapping": (op_lat, op_long),
            "position": None,
        }
        self._update_ngl_view_button_state()

        # Obtain the geographic extent of the layer
        extent = layer.extent()

        # Access the map canvas and apply zoom
        canvas = iface.mapCanvas()
        canvas.setExtent(extent)
        canvas.refresh()


        # Add mapbase is required
        if self.mapbase.isChecked():
            op_url = self.tiles.currentText()
            url = op_tiles[op_url]
            rasterLayer = QgsRasterLayer("type=xyz&url=" + url, str(op_url), "wms")
            QgsProject.instance().addMapLayer(rasterLayer, False)
            root = QgsProject.instance().layerTreeRoot()
            root.insertLayer(-1, rasterLayer)

        self.Boton1.setEnabled(True)
        self.adv_1.setText("<font style='color:#32CD32'><b>The CORS has been loaded successfully.</b></font>")


    def enab_up_data(self):
        self.up_data2.setEnabled(True)


