    def unit_circle_epoch(self):
        #Render unit circle plotting points with a temporal color gradient from Color_d1 to Color_d2.
        # Mark active plot and clear previous scene references
        self.grafic._active_plot = "circle"

        # Cancel fitting from the previously displayed plot.
        if hasattr(self, "_qq_auto_fit"):
            self._qq_auto_fit._timer.stop()
            self._qq_auto_fit._labels = []
            self._qq_auto_fit._bounds = None

        self.sl_met.setEnabled(True)

        try:
            epoch_data = self._get_radial_epoch_data()
        except (ValueError, TypeError, OverflowError) as error:
            QMessageBox.warning(self, "Unit Circle plot by epoch", str(error))
            return

        renderer = self._ensure_circle_renderer()
        renderer.clear()

        self.Bt_ind.setEnabled(False)

        act_met = self.sl_met.currentText()
        distances = l_dist if act_met == "Absolute" else l_dist_r
        azimuths = l_azimut if act_met == "Absolute" else l_azimut_r
        total_pts = len(distances)

        if total_pts == 0:
            self.az_mean_c.setEnabled(False)
            self.des_cir_c.setEnabled(False)
            return

        # Enable overlay controls without changing their checked state.
        self.az_mean_c.setEnabled(True)
        self.des_cir_c.setEnabled(True)

        # Setup scene geometry based on circle renderer
        rect, center, radius = renderer.geometry()
        start = QPointF(center)

        # Retrieve start and end colors for the temporal interpolation
        colors = tuple(self._plot_color(name) for name in ("Color_d1", "Color_mean", "Color_d2"))
        ring_color = self._plot_color("Color_ring")

        # Read the current presentation setting on every redraw.
        num_rings = max(
            1,
            int(self.anillos.value()),
        )

        self.long_a.setText(
            str(round(1.0 / num_rings, 2))
        )

        # Draw guide rings and their normalized identifiers.
        for i in range(num_rings):
            fraction = (i + 1) / num_rings
            r_ring = radius * fraction

            circle_item = QGraphicsEllipseItem(
                start.x() - r_ring,
                start.y() - r_ring,
                r_ring * 2,
                r_ring * 2,
            )

            circle_item.setPen(QPen(ring_color))
            circle_item.setZValue(1)

            self.circular.addItem(circle_item)

            ring_text = QGraphicsSimpleTextItem(
                str(round(fraction, 2))
            )

            ring_text.setRotation(0.0)

            offset = (
                math.sqrt(2.0) / 2.0
            ) * r_ring

            ring_text.setPos(
                start.x() + offset,
                start.y() + offset,
            )

            self.circular.addItem(ring_text)

        # Read the current sector count on every redraw.
        sect = max(
            1,
            int(self.section_a.value()),
        )

        deg_sec = 360.0 / sect

        self.deg_a.setText(
            f"{round(deg_sec, 0)}°"
        )

        sector_color = self._plot_color("Color_bin")

        # Draw radial guides and horizontal angle labels.
        for i in range(sect):
            ang = i * deg_sec
            angle_radians = ang * math.pi / 180

            east = math.sin(angle_radians)
            north = math.cos(angle_radians)

            deg_line = QGraphicsLineItem(
                start.x(),
                start.y(),
                start.x() + east * radius * 1.05,
                start.y() - north * radius * 1.05,
            )

            deg_line.setPen(
                QPen(
                    sector_color,
                    1.0,
                    Qt.SolidLine,
                    Qt.FlatCap,
                )
            )

            self.circular.addItem(deg_line)

            tex_val = int(deg_sec * i)

            t_item = QGraphicsSimpleTextItem(
                str(tex_val)
            )

            t_item.setRotation(0.0)

            t_item.setPos(
                start.x() + east * radius * 1.1 - 8,
                start.y() - north * radius * 1.1 - 8,
            )

            self.circular.addItem(t_item)

            if tex_val == 0:
                renderer.set_north_label(
                    t_item,
                    start,
                    radius,
                )

        # Count occurrences for radial stacking
        counter = collections.Counter()
        dot_diameter = radius / 50.0

        for i in range(total_pts):
            az = float(azimuths[i])
            az_round = round(az, 0)
            veces = counter[az_round]
            counter[az_round] += 1

            lon = max(0.0, radius - (veces / 0.5))
            pos_x = math.sin(math.radians(az_round)) * lon
            pos_y = math.cos(math.radians(az_round)) * lon

            # Interpolate RGB values based on temporal progression from index 0 to total_pts - 1
            ratio = epoch_data["vertices"][i][2]
            pt_color = self._radial_epoch_color(ratio, colors)

            # Create and add the point item with interpolated color
            pt_item = QGraphicsEllipseItem(start.x() + pos_x - (dot_diameter / 2.0), start.y() - pos_y - (dot_diameter / 2.0), dot_diameter, dot_diameter)
            pt_item.setPen(QPen(pt_color, 1.0, Qt.SolidLine, Qt.FlatCap))
            pt_item.setBrush(QBrush(pt_color, Qt.SolidPattern))
            pt_item.setZValue(2)
            self.circular.addItem(pt_item)

        # Add title item
        title = QGraphicsSimpleTextItem("Unit circle plot by epoch")
        title.setPos(10, 10)
        self.circular.addItem(title)

        # Create overlays from the same observations used by the epoch plot.
        self._create_epoch_circle_overlays(
            center=start,
            radius=radius,
            azimuths=azimuths,
        )

        start_jd, end_jd = epoch_data["start"], epoch_data["end"]
        dates = tuple(self.julian_to_yyyy_mm_dd(value) for value in (start_jd, (start_jd + end_jd) / 2, end_jd))
        self._add_radial_epoch_legend(renderer, start, radius, colors, dates)        

        # Fit the completed scene and apply the current overlay settings.
        renderer.finish()
        self._update_circle_overlays()

    def _cancel_circular_kde_preparation(self, *args):
        """Invalidate the request before cancelling its worker."""
        task = getattr(
            self,
            "_circular_kde_task",
            None,
        )

        self._circular_kde_request = None
        self._circular_kde_task_key = None
        self._circular_kde_task = None

        if task is not None:
            task.cancel()

    def _schedule_circular_kde_preparation(self):
        """Prefetch the current KDE without changing the selected graph."""
        if self._reset_in_progress:
            return

        if not self._datos_graficos_listos:
            return

        if self._circle_statistics is None:
            return

        try:
            self._ensure_circular_kde_preparation()

        except (
            ValueError,
            TypeError,
            OverflowError,
        ) as error:
            QgsMessageLog.logMessage(
                str(error),
                "GVDA",
                Qgis.Warning,
            )

    def _ensure_circular_kde_preparation(self):
        """Return a matching preparation or start a numerical worker."""
        epoch_data = self._get_radial_epoch_data()

        azimuths = tuple(epoch_data["azimuths"])
        ratios = tuple(
            vertex[2]
            for vertex in epoch_data["vertices"]
        )

        kappa, bands = self._circular_kde_parameters

        key = (
            self._radial_epoch_key,
            azimuths,
            ratios,
            kappa,
            bands,
        )

        cache = getattr(
            self,
            "_circular_kde_cache",
            None,
        )

        if cache is not None and cache[0] == key:
            return epoch_data, kappa, bands, cache[1]

        error = getattr(
            self,
            "_circular_kde_error",
            None,
        )

        if error is not None and error[0] == key:
            raise ValueError(error[1])

        if (
            getattr(self, "_circular_kde_task_key", None)
            == key
        ):
            return epoch_data, kappa, bands, None

        self._cancel_circular_kde_preparation()

        token = object()
        dialog_ref = weakref.ref(self)

        self._circular_kde_request = token
        self._circular_kde_task_key = key
        self._circular_kde_error = None

        def calculate(task, azimuths, ratios, kappa, bands):
            # The worker must not access widgets or dialog state.
            if task.isCanceled():
                return None

            result = prepare_circular_kde_epoch(
                azimuths,
                ratios,
                kappa,
                bands,
            )

            return None if task.isCanceled() else result

        def completed(exception, result=None):
            dialog = dialog_ref()

            if dialog is None or sip.isdeleted(dialog):
                return

            # Reject callbacks from replaced or cancelled requests.
            if dialog._circular_kde_request is not token:
                return

            dialog._circular_kde_task = None
            dialog._circular_kde_task_key = None
            dialog._circular_kde_request = None

            if dialog._reset_in_progress:
                return

            if not dialog._datos_graficos_listos:
                return

            if dialog._circle_statistics is None:
                return

            if dialog._radial_epoch_key != key[0]:
                return

            if (
                dialog._circular_kde_parameters
                != (kappa, bands)
            ):
                return

            selected = (
                dialog.cb_grafic.currentData()
                == "circular_kde_epoch"
            )

            if exception is None and result is None:
                exception = RuntimeError(
                    "Preparation cancelled; use Apply to retry."
                )

            if exception is not None:
                message = (
                    "Circular KDE: "
                    f"{type(exception).__name__}: {exception}"
                )

                dialog._circular_kde_error = (
                    key,
                    message,
                )

                QgsMessageLog.logMessage(
                    message,
                    "GVDA",
                    Qgis.Warning,
                )

                if selected:
                    dialog._ensure_circle_renderer().clear()

                    QMessageBox.warning(
                        dialog,
                        "Circular KDE plot by epoch",
                        message,
                    )

                return

            dialog._circular_kde_cache = (
                key,
                result,
            )

            # Publish only if this graph is still selected.
            if selected:
                dialog._render_selected_graph(
                    "circular_kde_epoch"
                )

        task = QgsTask.fromFunction(
            "GVDA: prepare circular KDE plot by epoch",
            calculate,
            on_finished=completed,
            azimuths=azimuths,
            ratios=ratios,
            kappa=kappa,
            bands=bands,
        )

        self._circular_kde_task = task
        QgsApplication.taskManager().addTask(task)

        return epoch_data, kappa, bands, None


    def circular_kde_epoch(self):
        """Render circular density with additive epoch-colored layers."""
        self.grafic._active_plot = "circle"

        if hasattr(self, "_qq_auto_fit"):
            self._qq_auto_fit._timer.stop()
            self._qq_auto_fit._labels = []
            self._qq_auto_fit._bounds = None

        self.sl_met.setEnabled(True)

        try:
            (
                epoch_data,
                kappa,
                bands,
                prepared,
            ) = self._ensure_circular_kde_preparation()

        except (
            ValueError,
            TypeError,
            OverflowError,
        ) as error:
            QMessageBox.warning(
                self,
                "Circular KDE plot by epoch",
                str(error),
            )
            return

        if prepared is None:
            # Do not display the previous context while preparation runs.
            renderer = self._ensure_circle_renderer()
            renderer.clear()

            self.az_mean_c.setEnabled(False)
            self.des_cir_c.setEnabled(False)

            rect, center, radius = renderer.geometry()

            label = QGraphicsSimpleTextItem(
                f"Circular KDE plot by epoch (K={kappa})"
                " — Preparing..."
            )
            label.setPos(
                rect.left() + 10,
                rect.top() + 10,
            )
            self.circular.addItem(label)

            renderer.finish()
            return

        azimuths = tuple(epoch_data["azimuths"])
        ratios = tuple(
            vertex[2]
            for vertex in epoch_data["vertices"]
        )

        renderer = self._ensure_circle_renderer()
        renderer.clear()

