    def _invalidate_station_analysis(self, reason):
        """Invalidate results without clearing column selections."""
        # Changing the active station does not invalidate the batch inputs.
        membership_reasons = {"cors_se_insert", "cors_se_remove", "cors_se_model_reset"}

        # Membership changes do not discard completed station results.
        if reason not in membership_reasons | {"tb_stations", "cb_stat_sel"}:
            self._cancel_ngl_batch_view()
            self.bt_view_batch.setEnabled(False)

        if reason in {"initial", "service", "load_file", "clear_selected_stations"}:
            self._ngl_batch_station_cache.clear()

        self._validation_graphs_ready = False
        self._validation_plot_failed = False

        # Do not carry observation coordinates into the next station.
        self._sync_archive_exist_coord()

        self.Bt_ind.setEnabled(False)
        self.Bt_batch.setEnabled(False)

        self._datos_graficos_listos = False
        self._invalidate_circle_geometry()
        self._invalidate_density_preparation()
        self._invalidate_radial_epoch_plot()
        self._data_table_context_key = None
        self._circle_statistics = None
        self._circle_statistics_key = None
        self.bt_view.setEnabled(False)

        self._analysis_generation = (getattr(self,"_analysis_generation",0,)+ 1)

        self._azimuth_distance_time_cache = None

        time_fit = getattr(self, "_time_series_auto_fit", None)
        if time_fit is not None:
            time_fit.clear()

        self._analysis_valid = False
        self._analysis_reset_reason = reason

        # Restore Absolute without triggering redraw.
        signals_were_blocked = self.sl_met.blockSignals(True)

        try:
            self.sl_met.setCurrentIndex(0)
        finally:
            self.sl_met.blockSignals(
                signals_were_blocked
            )

        self._reset_circular_analysis_state()

        # Previous results must not remain accessible.
        for index in (2, 3, 4):
            self.tab_princ.setTabEnabled(
                index,
                False,
            )

        if self.tab_princ.currentIndex() in (2, 3, 4):
            for index in (1, 0):
                if self.tab_princ.isTabEnabled(index):
                    self.tab_princ.setCurrentIndex(
                        index
                    )
                    break

        hist_fit = getattr(self, "_histogram_auto_fit", None)
        if hist_fit is not None:
            hist_fit.clear()


    # Resize the window
    def resizeEvent(self, event):
        """Preserve the existing graphics-view resize behavior.

        North and East validation canvases are resized automatically
        by their container layouts.
        """
        super().resizeEvent(event)

        # Preserve resizing for the existing graphics-view plot.
        if self.grafic.scene():
            rect = self.grafic.scene().itemsBoundingRect()
            self.grafic.scene().setSceneRect(rect)
            self.grafic.fitInView(
                rect,
                Qt.KeepAspectRatio,
            )   

    def _toggle_module_histogram_spinbox(self, text):
        """Show the spinbox only when 'Module Histogram' is selected."""
        is_module_histogram = text == "Distance Histogram"
        
        # Replace 'clas_mod' with the actual name of your QSpinBox
        self.clas_mod.setVisible(is_module_histogram)
        

