            t5 = QTableWidgetItem()
            t5.setTextAlignment(QtCore.Qt.AlignVCenter | QtCore.Qt.AlignRight)
            dist_t=round(list_residual[i],dec_n)
            t5.setData(Qt.DisplayRole, f"%0.{dec_n}f"% dist_t)    

            t6 = QTableWidgetItem()
            t6.setTextAlignment(QtCore.Qt.AlignVCenter | QtCore.Qt.AlignRight)
            dist_tr=round(list_residual[i]/list_int[pos],dec_n)
