    def draw_asv(self):
        """Draw anomaly segments using row-aligned observation positions."""
        if self._reset_in_progress or not self._datos_graficos_listos:
            return

        catalog = self.service.currentText().strip().upper()

        # ZIP and EPOS anomaly segments use Relative results only.
        relative_only = self.input_source == "archive" or (
            self.input_source == "remote" and catalog == "EPOS"
        )
        if relative_only and self.sl_met.currentText() != "Relative":
            return

        if not self._ensure_circle_statistics():
            return

        if not list_outliers:
            QMessageBox.information(
                self,
                "Anomaly vectors",
                "There are no anomaly records to draw.",
            )
            return

        catalog = self.service.currentText().strip().upper()
        station_id = str(self.active_station_id or "").strip().upper()
        remote = (
            self.input_source == "remote"
            and self.validation_source == "remote"
        )

        positions = {}
        archive_layer_name = None

        try:
            if self.input_source == "archive":
                archive_layer_name, positions = (
                    self._archive_anomaly_positions()
                )

            elif remote:
                if catalog == "JPL":
                    raise ValueError(
                        "The JPL catalog reference position is not a trajectory."
                    )

                if catalog not in {"NGL", "EPOS"}:
                    raise ValueError(
                        "Anomaly segments require observation coordinates."
                    )

                station_id, frame, valid_rows, _ = (
                    self._get_ngl_view_rows()
                )

                if len(frame) != len(df):
                    raise ValueError(
                        "The station coordinates and analysis dataframe "
                        "do not have matching row counts."
                    )

                # Match the coordinate document to the validated epoch order.
                epoch_column = self.sel_time.currentText()
                raw_epochs = tuple(
                    str(frame.iloc[i][epoch_column]).strip()
                    for i in range(len(frame))
                )

                if getattr(
                    self, "_radial_epoch_time_signature", None
                ) != (epoch_column, raw_epochs):
                    raise ValueError(
                        "Validate the current station epochs before "
                        "drawing anomaly vectors."
                    )

                positions = {
                    row_index: (latitude, longitude)
                    for row_index, latitude, longitude in valid_rows
                }

            else:
                op_lat = self.lat.currentText()
                op_long = self.longi.currentText()

                if not op_lat.strip() or not op_long.strip():
                    raise ValueError(
                        "Select the latitude and longitude columns before "
                        "drawing anomaly vectors."
                    )

                lat_column = self._ngl_column_position(df, op_lat)
                lon_column = self._ngl_column_position(df, op_long)

                for row_index in range(len(df)):
                    position = self._normalize_ngl_position(
                        df.iat[row_index, lat_column],
                        df.iat[row_index, lon_column],
                    )
                    if position is not None:
                        positions[row_index] = position

        except (ValueError, TypeError, KeyError, IndexError) as error:
            QMessageBox.warning(
                self,
                "Anomaly vectors",
                str(error),
            )
            return

        if archive_layer_name is not None:
            layer_name = archive_layer_name
        elif remote:
            layer_name = f"{catalog}_{station_id}_anomalies"
        else:
            layer_name = (
                f"{self._local_station_layer_name()}_anomalies"
            )

        # Define type of geometry (line) and CRS
        geom_type = QgsWkbTypes.LineGeometry
        crs = "EPSG:4326"  # CRS WGS 84

        # Create the temporal layer
        uri = "LineString?crs=" + crs
        layer = QgsVectorLayer(uri, layer_name, "memory")

        # Define fields of the attrib's tables 
        if Qgis.versionInt() >= 33800:
            fields = [
                QgsField("Initial_epoch", QMetaType.Type.QString),
                QgsField("Final_epoch", QMetaType.Type.QString),
                QgsField("Interval (days)", QMetaType.Type.Int),
                QgsField("Diff_n", QMetaType.Type.Double),
                QgsField("Diff_e", QMetaType.Type.Double),
                QgsField("Distance", QMetaType.Type.Double),
                QgsField("Dist_epoch", QMetaType.Type.Double),
                QgsField("Azimut", QMetaType.Type.Double),
                QgsField("Type", QMetaType.Type.QString)
            ]
        else:
            fields = [
                QgsField("Initial_epoch", QVariant.String),
                QgsField("Final_epoch", QVariant.String),
                QgsField("Interval (days)", QVariant.Int),
                QgsField("Diff_n", QVariant.Double),
                QgsField("Diff_e", QVariant.Double),
                QgsField("Distance", QVariant.Double),
                QgsField("Dist_epoch", QVariant.Double),
                QgsField("Azimut", QVariant.Double),
                QgsField("Type", QVariant.String)
            ]          
        layer.dataProvider().addAttributes(fields)
        layer.updateFields()

        # Enable edit
        layer.startEditing()

        skipped_segments = 0
        # Add Line of list
        for i in range(len(list_outliers)):
            pos = list_outliers[i]

            # Never bridge missing coordinate rows.
            first_position = positions.get(pos)
            final_position = positions.get(pos + 1)

            if first_position is None or final_position is None:
                skipped_segments += 1
                continue

            lat1, lon1 = first_position
            lat2, lon2 = final_position

            feature1 = QgsFeature(layer.fields())
            points = [
                QgsPointXY(lon1, lat1),
                QgsPointXY(lon2, lat2),
            ]
            feature1.setGeometry(
                QgsGeometry.fromPolylineXY(points)
            )

            if (list_residual[i]/list_int[pos])>=desv_sta_c:
                tx_asv="Anomaly"
            else:
                tx_asv="Meets_the_threshold"

            feature1.setAttributes([
                self._epoch_date_iso(pos),
                self._epoch_date_iso(pos + 1),
                int(list_int[pos]),
                float(list_dn[pos+1]),
                float(list_de[pos+1]),
                float(list_residual[i]),
                float(list_residual[i]/list_int[pos]),
                float(l_azimut_r[pos]),
                str(tx_asv)
            ])
            layer.addFeature(feature1)

        # Save the change
        layer.commitChanges()

        layer.updateExtents()

        if layer.featureCount() == 0:
            QMessageBox.warning(
                self,
                "Anomaly vectors",
                "No anomaly segment has valid coordinates "
                "at both endpoint observations.",
            )
            return

        if skipped_segments:
            iface.messageBar().pushMessage(
                "GVDA",
                (
                    f"{layer_name}: {skipped_segments} segments skipped "
                    "because an endpoint has no valid coordinates."
                ),
                level=Qgis.Warning,
                duration=8,
            )


        # Generates arrow symbols in vectors.
        ruta_estilo = os.path.join(os.path.dirname(__file__), 'scripts', 'rows.qml') 
        processing.run("native:setlayerstyle", {'INPUT':layer,'STYLE':ruta_estilo})

        # Add layer to the proyect
        # Publish only when this context and output are not already present.
        try:
            if not self._publish_unique_output(layer, "anomalies"):
                return
        except Exception as error:
            QMessageBox.warning(
                self,
                "Anomaly vectors",
                str(error),
            )
            return

        # Transform the layer extent to the map canvas CRS.
        try:
            canvas = iface.mapCanvas()
            bounds = layer.extent()
            center = bounds.center()

            half_width = max(bounds.width() * 0.60, 0.0005)
            half_height = max(bounds.height() * 0.60, 0.0005)

            geographic_extent = QgsRectangle(
                max(-180.0, center.x() - half_width),
                max(-90.0, center.y() - half_height),
                min(180.0, center.x() + half_width),
                min(90.0, center.y() + half_height),
            )

            transform = QgsCoordinateTransform(
                layer.crs(),
                canvas.mapSettings().destinationCrs(),
                QgsProject.instance(),
            )
            map_extent = transform.transformBoundingBox(
                geographic_extent
            )

            if not all(
                math.isfinite(value)
                for value in (
                    map_extent.xMinimum(),
                    map_extent.yMinimum(),
                    map_extent.xMaximum(),
                    map_extent.yMaximum(),
                )
            ):
                raise ValueError(
                    "The transformed map extent is not finite."
                )

            canvas.setExtent(map_extent)
            canvas.refresh()

        except Exception as error:
            iface.messageBar().pushMessage(
                "GVDA",
                f"{layer_name}: layer created, but map zoom failed: {error}",
                level=Qgis.Warning,
                duration=8,
            )


    @staticmethod
    def date_to_julian(value, item):
        """Convert calendar or decimal-year input to JD without dropping fractions."""
        if item == "JJJJJ.JJJJJ":
            # The public GNSS Julian option represents Modified Julian Date.
            mjd = float(value)

            if not math.isfinite(mjd) or not 0 <= mjd < 1000000:
                raise ValueError("Expected a finite GNSS MJD value, not a full astronomical JD.")

            return mjd + 2400000.5

        text = str(value).strip()

        if item == "YYYYMMDD":
            if re.fullmatch(r"[0-9]{8}", text) is None:
                raise ValueError("The epoch must match YYYYMMDD.")

            stamp = datetime.strptime(text, "%Y%m%d")

        elif item in ("YYYY.YYYY", "YYYY.YYYYYYYY"):
            places = len(item.split(".")[1])

            if re.fullmatch(rf"[0-9]{{4}}\.[0-9]{{{places}}}", text) is None:
                raise ValueError("The decimal year does not match the selected format.")

            value = float(text)
            year = math.floor(value)

            if not 1 <= year < 9999:
                raise ValueError("Decimal year is outside the supported range.")

            start, end = datetime(year, 1, 1), datetime(year + 1, 1, 1)
            stamp = start + (end - start) * (value - year)

        else:
            raise ValueError("Unsupported calendar input format.")

        return 2451544.5 + (stamp - datetime(2000, 1, 1)).total_seconds() / 86400.0

    
    @staticmethod
    def julian_to_yyyy_mm_dd(jd):
        """Format an astronomical JD using the proleptic Gregorian calendar."""
        jd = float(jd)

        if not math.isfinite(jd):
            raise ValueError("Julian date must be finite.")

        stamp = datetime(2000, 1, 1) + timedelta(days=jd - 2451544.5)
        return f"{stamp.year:04d}-{stamp.month:02d}-{stamp.day:02d}"

    def _epoch_date_iso(self, index):
        """Return the ISO label cached when the epoch column was validated."""
        if len(self._epoch_iso_dates) != len(d_time_j) or not self._epoch_iso_dates:
            raise ValueError("Validate the epoch column before displaying dates.")

        return self._epoch_iso_dates[index]


    def cal_interval(self):
        """Validate epochs once per session and retain canonical JD and ISO dates."""
        if self.validation_source == "archive":
            member_index = getattr(self, "_archive_active_member", None)
            state = self._archive_station_states.get(member_index)

            if state is not None:
                state["epoch_error"] = None
                state["validation_error"] = None

        # Block analysis until the current station epochs and plots are ready.
        self._archive_invalidate_association()

        self._validation_graphs_ready = False
        self._validation_plot_failed = False
        self.Bt_ind.setEnabled(False)
        self.Bt_batch.setEnabled(False)

        global d_time_j, list_int, val_inter

        d_time_j.clear()
        list_int, val_inter = [], ""
        self._epoch_iso_dates = ()
        self._radial_epoch_time_signature = None

        if hasattr(self, "_invalidate_radial_epoch_plot"):
            self._invalidate_radial_epoch_plot()

        column = self.sel_time.currentText()

        if not column or column not in df.columns or df.empty:
            return

        try:
            item = self._epoch_formats_by_column.get(column)
            
            if item is None:
                formats = (
                    "YYYYMMDD",
                    "JJJJJ.JJJJJ",
                    "YYYY.YYYYYYYY",
                    "YYYY.YYYY",
                )
                tooltips = (
                    "YYYYMMDD / Calendar Date",
                    "JJJJJ.JJJJJ / Modified Julian Date (MJD)",
                    "YYYY.YYYYYYYY / Decimal Year",
                    "YYYY.YYYY / Decimal Year",
                )

                # Accept the original format identifier on explicit selection.
                dialog = QInputDialog(self)
                dialog.setWindowTitle("Epoch format")
                dialog.setLabelText(
                    "Select an epoch format to continue:"
                )
                dialog.setComboBoxItems(formats)
                dialog.setComboBoxEditable(False)
                dialog.setOption(QInputDialog.NoButtons, True)

                combo = dialog.findChild(QComboBox)
                if combo is not None:
                    for index, tooltip in enumerate(tooltips):
                        combo.setItemData(
                            index, tooltip, Qt.ToolTipRole
                        )

                    # Require a selection instead of accepting a default.
                    combo.setCurrentIndex(-1)
                    combo.activated[int].connect(
                        lambda _index: dialog.accept()
                    )

                accepted = bool(dialog.exec_())
                selected = dialog.textValue() if accepted else ""
                dialog.deleteLater()
                
                if not accepted:
                    return

                item = selected

            # Preserve the row-wise epoch access used by the original implementation.
            raw_values = tuple(str(df.iloc[i][column]).strip() for i in range(len(df)))
            converted = tuple(self.date_to_julian(value, item) for value in raw_values)

            if len(converted) < 2 or not all(math.isfinite(value) for value in converted):
                raise ValueError("At least two finite epochs are required.")

            intervals = [right - left for left, right in zip(converted, converted[1:])]

            if any(value <= 0 for value in intervals):
                raise ValueError("Epochs must be strictly increasing.")

            iso_dates = tuple(self.julian_to_yyyy_mm_dd(value) for value in converted)

        except (ValueError, TypeError, OverflowError) as error:
            # Invalidate results without deleting the user's column mappings.
            self._request_station_analysis_reset("epoch_validation_failed")
            self._clear_validation_views()
            self.progressBar.setValue(0)

            self._validation_notice_html = f"<font color='#FF0000'><b>{error}</b></font>"
            if self.validation_source == "archive":
                self._epoch_formats_by_column.pop(column, None)

                member_index = self._archive_active_member
                state = self._archive_station_states.get(member_index)
                if state is not None:
                    state["epoch_error"] = str(error)
                    state["validation_error"] = str(error)

                self._refresh_validation_notice()
            else:
                self.lb_adv1.setText(self._validation_notice_html)
            return

            self.lb_adv1.setText(f"<font color='#FF0000'><b>{error}</b></font>")
            self._clear_validation_views()
            self.progressBar.setValue(0)
            self.sel_time.setCurrentIndex(0)
            self.neu_n.clear()
            self.neu_e.clear()
            return

        # Commit the session criterion only after every epoch is valid.
        self._epoch_format = item
        self._epoch_formats_by_column[column] = item
        d_time_j[:] = converted
        list_int = intervals
        self._epoch_iso_dates = iso_dates
        self._radial_epoch_time_signature = (column, raw_values)
        self._data_table_context_key = None

        # Preserve the existing interval-summary behavior.
        counts = dict(collections.Counter(intervals))
        val_inter = round(max(counts, key=counts.get),1)

        self.label_47.setText(f"Initial Epoch: {iso_dates[0]}")
        self.label_46.setText(f"Final Epoch: {iso_dates[-1]}")
        self.label_16.setText(f"Interval Epoch: {val_inter:g} days")
        self.label_45.setText(f"Number of Interruptions: {len(counts) - 1}")
        self.lb_adv1.setText("<font color='#297500'><b>Epoch format validated; dates are displayed as YYYY-MM-DD.</b></font>")

        # Restore available component choices only if a previous error emptied them.
        for selector in (self.neu_n, self.neu_e):
            if selector.count() == 0:
                previous_signal_state = selector.blockSignals(True)
                try:
                    selector.addItem("")
                    selector.addItems(list_col)
                finally:
                    selector.blockSignals(previous_signal_state)

        # Rebuild validation data when the existing column mapping is complete.
        # Validate components only when the complete mapping is available.
        if not self._get_missing_mapping_roles():
            self.chan_neu()
        elif self.validation_source == "archive":
            self._refresh_validation_notice()

            
    def _on_epoch_selection_changed(self, column_name):
        """Clear validation results when the epoch selection is empty.

        The active dataframe, cached station documents, and North/East
        column selections remain unchanged.
        """
        if self.validation_source == "archive":
            member_index = getattr(self, "_archive_active_member", None)
            state = self._archive_station_states.get(member_index)

            if state is not None:
                state["epoch_error"] = None
                state["validation_error"] = None

            self._clear_validation_views()
            d_time_j.clear()
            self._epoch_iso_dates = ()
            self._radial_epoch_time_signature = None
            self._epoch_format = None

            self._archive_invalidate_association()
            self._refresh_validation_notice()
            return

        if column_name.strip():
            return

        self._clear_validation_views()
        self.progressBar.setValue(0)


    def hist_mod(self):
        self.clas_mod.setEnabled(True)
        self.red_mode_s.setEnabled(False)
        clas=self.clas_mod.value()
        act_met = self.sl_met.currentText()
        self.az_mean_c.setEnabled(False)
        self.des_cir_c.setEnabled(False)
        self.bt_ano.setEnabled(False)

        # Stop previous fitting callbacks before replacing scene items.
        if hasattr(self, "_qq_auto_fit"):
            self._qq_auto_fit._timer.stop()
            self._qq_auto_fit._labels = []
            self._qq_auto_fit._bounds = None

        time_fit = getattr(self, "_time_series_auto_fit", None)
        if time_fit is not None:
            time_fit.clear()

        hist_fit = getattr(self, "_histogram_auto_fit", None)
        if hist_fit is not None:
            hist_fit.clear()

        self.grafic._active_plot = "hist"

        lis_mod=list()
        lis_mod.clear()

        if act_met=="Absolute":
            for i in range(len(l_dist)):
                lon_feat2 = l_dist[i]
                lis_mod.append(lon_feat2)
        else:
            for i in range(len(l_dist_r)):
                lon_feat2 = l_dist_r[i]
                lis_mod.append(lon_feat2)

        self._ensure_circle_renderer().clear()

        cant=len(lis_mod)
        datos=cant

        col_f=self.sel_time.currentText()
        self.num_d.setText(f"Data Number: {str(datos)}")

        viewprect = QRectF(self.grafic.viewport().rect())
        ventana=viewprect
        self.grafic.setSceneRect(viewprect)
        left = self.grafic.sceneRect().left()
        right = self.grafic.sceneRect().right()
        width = (right - left)-20
        top = self.grafic.sceneRect().top()
        bottom = self.grafic.sceneRect().bottom()
        height = (bottom - top)-20

        if cant>0:
            lon_feat_max=max(lis_mod)
            rang=lon_feat_max/clas

            frecuencias, extremos = np.histogram(lis_mod, bins=clas)

            size = width
            if width > height:
                size = height
            padding = 15
            maxlength = (size / 2) - padding * 2

            center = QPoint(int(left + (width / 2)),int(top + (height / 2)))
            # The scene geomatry of the center point
            start = QPointF(self.grafic.mapToScene(center))

            ancho=maxlength
            height = (bottom - top)*0.85
            alto=height-(height*0.02)
            alto2=(height/2.02)

            # Map the actual histogram edges to the complete plotting width.
            x = 2.0 * ancho
            bin_min = float(extremos[0])
            bin_max = float(extremos[-1])
            bin_span = bin_max - bin_min
            frec_max = int(max(frecuencias))

            # Reserve at least five percent headroom and select integer tick intervals.
            target_top = frec_max * 1.05
            raw_step = target_top / 4.0
            step_unit = 10.0 ** math.floor(math.log10(raw_step))
            step_factor = next(value for value in (1.0, 1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 6.0, 8.0, 10.0) if value >= raw_step / step_unit)
            y_tick_step = max(1, int(math.ceil(step_unit * step_factor)))
            y_axis_max = int(math.ceil(target_top / y_tick_step) * y_tick_step)
            y_ticks = tuple(range(0, y_axis_max + 1, y_tick_step))
            plot_left = start.x() - ancho
            plot_bottom = start.y() + alto2
            plot_height = 2.0 * alto2

            # Read applied colors without committing pending button changes.
            bar_brush = QBrush(self._plot_color("Color_dot"))
            bar_pen = QPen(Qt.NoPen)
            line_pen = QPen(self._plot_color("Color_line"), 1.0, Qt.SolidLine, Qt.FlatCap, Qt.RoundJoin)
            line_pen.setCosmetic(True)
            line_path = QPainterPath()

            # Draw bars within their actual intervals and connect their centers.
            for index, frequency in enumerate(frecuencias):
                edge_left = plot_left + x * (float(extremos[index]) - bin_min) / bin_span
                edge_right = plot_left + x * (float(extremos[index + 1]) - bin_min) / bin_span
                bin_width = edge_right - edge_left
                bar_height = plot_height * float(frequency) / y_axis_max
                bar_top = plot_bottom - bar_height
                center_x = (edge_left + edge_right) / 2.0

                if frequency > 0:
                    bar = self.circular.addRect(QRectF(edge_left + bin_width * 0.025, bar_top, bin_width * 0.95, bar_height), bar_pen, bar_brush)
                    bar.setZValue(2)

                if index == 0:
                    line_path.moveTo(center_x, bar_top)
                else:
                    line_path.lineTo(center_x, bar_top)

            # Keep the frequency line above the bars and reference grid.
            line_item = self.circular.addPath(line_path, line_pen, QBrush(Qt.NoBrush))
            line_item.setZValue(3)
            
            # Derive lighter grid colors from the applied presentation color.
            horizontal_color = QColor(self._plot_color("Color_bin"))
            vertical_color = QColor(horizontal_color)
            border_color = QColor(horizontal_color)

            horizontal_color.setAlphaF(horizontal_color.alphaF() * 0.30)
            vertical_color.setAlphaF(vertical_color.alphaF() * 0.18)
            border_color.setAlphaF(border_color.alphaF() * 0.65)

            horizontal_pen = QPen(horizontal_color, 1.0)
            vertical_pen = QPen(vertical_color, 1.0)
            border_pen = QPen(border_color, 1.0)

            horizontal_pen.setCosmetic(True)
            vertical_pen.setCosmetic(True)
            border_pen.setCosmetic(True)

            # Place horizontal guides at the actual frequency tick values.
            for tick_value in y_ticks[1:-1]:
                grid_y = plot_bottom - plot_height * tick_value / y_axis_max
                grid_item = self.circular.addLine(plot_left, grid_y, plot_left + x, grid_y, horizontal_pen)
                grid_item.setZValue(0)

            # Preserve the three internal vertical guides.
            for index in range(1, 4):
                grid_x = plot_left + x * index / 4.0
                grid_item = self.circular.addLine(grid_x, plot_bottom - plot_height, grid_x, plot_bottom, vertical_pen)
                grid_item.setZValue(0)

            # Draw the plot boundary separately to avoid duplicate edge guides.
            border_item = self.circular.addRect(QRectF(plot_left, plot_bottom - plot_height, x, plot_height), border_pen, QBrush(Qt.NoBrush))
            border_item.setZValue(1)             

            # Match the font used by the shared presentation formatter.
            hist_font = QFont("Sans Serif")
            hist_font.setPixelSize(12)
            hist_font.setBold(False)

            # Collect label anchors for resize-only presentation updates.
            hist_labels = []
            hist_font = QFont("Sans Serif")
            hist_font.setPixelSize(12)
            hist_font.setBold(False)

            def add_hist_label(text, anchor_x, anchor_y, horizontal="center", vertical="center", rotation=0.0, dx=0.0, dy=0.0):
                item = QGraphicsSimpleTextItem(text)
                item.setFont(hist_font)
                item.setPen(QPen(Qt.NoPen))
                item.setBrush(QBrush(Qt.black))
                item.setRotation(rotation)

                bounds = item.mapRectToParent(item.boundingRect())
                reference_x = {"left": bounds.left(), "center": bounds.center().x(), "right": bounds.right()}[horizontal]
                reference_y = {"top": bounds.top(), "center": bounds.center().y(), "bottom": bounds.bottom()}[vertical]

                item.setPos(anchor_x - reference_x + dx, anchor_y - reference_y + dy)
                self.circular.addItem(item)
                hist_labels.append((item, QPointF(anchor_x, anchor_y), horizontal, vertical, dx, dy))
                return item

            # Preserve the existing plot geometry during this first stage.
            plot_left = start.x() - ancho
            plot_right = plot_left + x
            plot_top = start.y() - alto2
            plot_bottom = start.y() + alto2
            plot_center_x = (plot_left + plot_right) / 2.0
            plot_center_y = (plot_top + plot_bottom) / 2.0

            # Match horizontal labels to the actual histogram domain.
            x_tick_items = []
            tick_decimals = max(0, 1 - math.floor(math.log10(bin_span / 4.0)))

            for index in range(5):
                fraction = index / 4.0
                tick_value = bin_min + bin_span * fraction
                tick_text = np.format_float_positional(tick_value, precision=tick_decimals, unique=False, fractional=True, trim="-")
                tick_item = add_hist_label(tick_text, plot_left + x * fraction, plot_bottom, vertical="top", dy=8.0)
                x_tick_items.append(tick_item)

            # Align integer frequency labels with the updated horizontal guides.
            y_tick_items = []

            for tick_value in y_ticks:
                tick_y = plot_bottom - plot_height * tick_value / y_axis_max
                tick_item = add_hist_label(str(tick_value), plot_left, tick_y, horizontal="right", dx=-10.0)
                y_tick_items.append(tick_item)

            # Reserve space using the actual dimensions of the tick labels.
            x_tick_height = max(item.boundingRect().height() for item in x_tick_items)
            y_tick_width = max(item.boundingRect().width() for item in y_tick_items)

            # Keep axis titles outside the complete tick-label bands.
            add_hist_label("Distance", plot_center_x, plot_bottom, vertical="top", dy=x_tick_height + 22.0)
            add_hist_label("Frequency", plot_left, plot_center_y, horizontal="right", rotation=270.0, dx=-y_tick_width - 28.0)

        else:
            text2 = QGraphicsSimpleTextItem(str("No Data"))
            text2.setPos(start.x(),start.y())
            self.circular.addItem(text2) 

            resul_1 = "Data Number: -"
            self.num_d.setText(resul_1)
            resul_1 = "Mean Azimuth: <b>-° -' -''</b>"
            self.az_mean_t.setText(resul_1)
            resul_7 = "Median Azimuth: <b>-° -' -''</b>"
            self.az_median_t.setText(resul_7)
            resul_7 = "Mode Azimuth: <b>-° -' -''</b>"
            self.az_mode_t.setText(resul_7)
            resul_7 = "Discrepancy: <b>-° -' -''</b>"
            self.lb_disc.setText(resul_7)
            resul_2 = "Mean resultant length: <b>-</b>"
            self.mod_med_t.setText(resul_2)
            resul_3 = "Circular Variance: <b>-</b>"
            self.var_cir_t.setText(resul_3)
