        linea += "header {background: #004466;color: #fff;padding: 20px;text-align: center;}\n"
        linea += "header h1 {margin: 0;}\n"
        linea += "main {max-width: 1000px;margin: 20px auto 40px auto;background: #fff;padding: 20px 25px 40px 25px;box-shadow: 0 2px 6px rgba(0,0,0,0.15);}\n"
        linea += "h2 {color: #004466;border-bottom: 2px solid #e0e0e0;padding-bottom: 5px;}\n"
        linea += "h3 {color: #006688;margin-top: 25px;}\n"
        linea += "p {margin: 8px 0;}\n"
        linea += "table {border: 2px solid blue; border-collapse: collapse; font-family: arial; width: 80%;}\n"
        linea += "td {padding: 5px;text-align: center;}\n"
        linea += "font.over {text-decoration: overline;}\n"
