    def clip(self):
        """Store the active graph as SVG in the internal graphics collection."""
        plot_id = getattr(self.grafic, "_active_plot", None)
        use_view_rendering = plot_id in ("azimuth_distance_time_series", "hist")

        if use_view_rendering:
            # Finish pending framing without rebuilding graph data.
            time_fit = getattr(self, "_time_series_auto_fit", None)

            # Complete the active presentation layout before exporting.
            fit_name = "_histogram_auto_fit" if plot_id == "hist" else "_time_series_auto_fit"
            export_fit = getattr(self, fit_name, None)

            if export_fit is not None:
                export_fit._timer.stop()
                export_fit.fit()

            source_rect = self.grafic.viewport().rect()
            width = source_rect.width()
            height = source_rect.height()

        else:
            # Preserve the existing scene-based export for other graphs.
            scene_rect = self.circular.sceneRect()
            width = int(scene_rect.width())
            height = int(scene_rect.height())

        if width <= 0 or height <= 0:
            QMessageBox.warning(
                self,
                "Copy graph",
                "The current graph has no valid export dimensions.",
            )
            return

        # Keep the output buffer alive until SVG painting is complete.
        byte_array = QByteArray()
        buffer = QBuffer(byte_array)

        if not buffer.open(QIODevice.WriteOnly):
            QMessageBox.warning(
                self,
                "Copy graph",
                "The SVG memory buffer could not be opened.",
            )
            return

        svg_data = b""

        try:
            svg_gen = QSvgGenerator()
            svg_gen.setOutputDevice(buffer)
            svg_gen.setSize(QSize(width, height))
            svg_gen.setViewBox(QRect(0, 0, width, height))

            if use_view_rendering:
                svg_gen.setResolution(max(1, int(self.grafic.viewport().logicalDpiX())))

            painter = QPainter()

            if not painter.begin(svg_gen):
                QMessageBox.warning(
                    self,
                    "Copy graph",
                    "The SVG painter could not be initialized.",
                )
                return

            try:
                painter.setRenderHint(
                    QPainter.Antialiasing,
                    True,
                )
                painter.setRenderHint(
                    QPainter.TextAntialiasing,
                    True,
                )

                if use_view_rendering:
                    target_rect = QRectF(0.0, 0.0, float(width), float(height))
                    painter.fillRect(target_rect, Qt.white)
                    self.grafic.render(painter, target_rect, source_rect, Qt.KeepAspectRatio)

                else:
                    self.circular.render(painter)

            finally:
                painter.end()

            # Read the SVG only after the painter has finalized the document.
            svg_data = bytes(byte_array.data())

        finally:
            buffer.close()

        if not svg_data:
            QMessageBox.warning(
                self,
                "Copy graph",
                "No SVG content was generated.",
            )
            return

        imagen.append(svg_data)
        self.ins_imag()


    def saveassvg(self, location=None):
        """Export the active graph while preserving its presentation geometry."""
        settings = QSettings()
        key = "/UI/lastShapefileDir"

        # Ignore signal arguments that are not explicit output paths.
        if isinstance(location, (str, os.PathLike)):
            savename = os.fspath(location)
        else:
            out_dir = settings.value(key, "")
            savename, _ = QFileDialog.getSaveFileName(
                self,
                "Save to SVG",
                out_dir,
                "SVG (*.svg)",
            )

        # Do not initialize an SVG device after dialog cancellation.
        if not savename:
            return

        if not savename.lower().endswith(".svg"):
            savename += ".svg"

        plot_id = getattr(self.grafic, "_active_plot", None)
        use_view_rendering = plot_id in ("azimuth_distance_time_series", "hist")

        if use_view_rendering:
            # Finish pending framing without rebuilding observations or statistics.
            time_fit = getattr(self, "_time_series_auto_fit", None)

            # Complete the active presentation layout before exporting.
            fit_name = "_histogram_auto_fit" if plot_id == "hist" else "_time_series_auto_fit"
            export_fit = getattr(self, fit_name, None)

            if export_fit is not None:
                export_fit._timer.stop()
                export_fit.fit()

            source_rect = self.grafic.viewport().rect()
            width = source_rect.width()
            height = source_rect.height()

            # Match the logical display DPI for the viewport-based export.
            resolution = max(1,int(self.grafic.viewport().logicalDpiX()),)

        else:
            # Preserve the existing scene-based export for the other graphs.
            scene_rect = self.grafic.sceneRect()
            width = int(scene_rect.width())
            height = int(scene_rect.height())
            resolution = 400

        if width <= 0 or height <= 0:
            QMessageBox.warning(
                self,
                "Save to SVG",
                "The current graph has no valid export dimensions.",
            )
            return

        svg_gen = QSvgGenerator()
        svg_gen.setFileName(savename)
        svg_gen.setSize(QSize(width, height))
        svg_gen.setViewBox(QRect(0, 0, width, height))
        svg_gen.setResolution(resolution)

        painter = QPainter()

        if not painter.begin(svg_gen):
            QMessageBox.warning(
                self,
                "Save to SVG",
                "The SVG file could not be opened for writing.",
            )
            return

        try:
            painter.setRenderHint(
                QPainter.Antialiasing,
                True,
            )
            painter.setRenderHint(
                QPainter.TextAntialiasing,
                True,
            )

            if use_view_rendering:
                target_rect = QRectF(0.0, 0.0, float(width), float(height))
                painter.fillRect(target_rect, Qt.white)
                self.grafic.render(painter, target_rect, source_rect, Qt.KeepAspectRatio)

            else:
                self.circular.render(painter)

        finally:
            painter.end()

        settings.setValue(
            key,
            os.path.dirname(savename),
        )    


    def ins_imag(self):
        if len(imagen)>0:
            cant=len(imagen)
            self.ilg.setEnabled(True)
            text2=f"Include {cant} Graphics (Clipboard)"
            self.ilg.setText(text2)        

    #Plot de azimuth before, after
    def azimut_a_dxdy(self,az_deg, longitud):
        rad = np.deg2rad(az_deg)
        dx = longitud * np.sin(rad)
        dy = longitud * np.cos(rad)
        return dx, dy

    def graphic_az(self,az_before, az_anomalo, az_after, long, output):
        # initial point
        x0, y0 = 0, 0

        # Vector 1: az_before
        dx1, dy1 = self.azimut_a_dxdy(az_before, long)
        x1, y1 = x0 + dx1, y0 + dy1

        # Vector 2: az_anomalo
        dx2, dy2 = self.azimut_a_dxdy(az_anomalo, long)
        x2, y2 = x1 + dx2, y1 + dy2

        # Vector 3: az_after
        dx3, dy3 = self.azimut_a_dxdy(az_after, long)
        x3, y3 = x2 + dx3, y2 + dy3

        fig, ax = plt.subplots(figsize=(8, 8))

        # Draw row
        ax.quiver(x0, y0, dx1, dy1, angles='xy', scale_units='xy', scale=1,
                  color='blue', width=0.005, label='az_before')
        ax.quiver(x1, y1, dx2, dy2, angles='xy', scale_units='xy', scale=1,
                  color='red', width=0.005, label='az_anomalo')
        ax.quiver(x2, y2, dx3, dy3, angles='xy', scale_units='xy', scale=1,
                  color='green', width=0.005, label='az_after')

        ax.plot([x0, x1, x2, x3], [y0, y1, y2, y3], 'ko', markersize=4)

        ax.text(x0 + dx1/2, y0 + dy1/2, 'az_before', color='blue')
        ax.text(x1 + dx2/2, y1 + dy2/2, 'az_anomaly', color='red')
        ax.text(x2 + dx3/2, y2 + dy3/2, 'az_after', color='green')

        ax.set_axis_off()

        # save figure in memory as bytes
        buffer = io.BytesIO()
        fig.savefig(buffer, format='jpeg', dpi=300, bbox_inches='tight')
        plt.close(fig)

        # Obtener bytes reales de la imagen
        buffer.seek(0)
        img_bytes = buffer.getvalue()

        # Convertir a base64
        img_base64 = base64.b64encode(img_bytes).decode('utf-8')
        
        return img_base64

