        date_format = now.strftime("%d/%m/%Y")

        linea += f"<header><h1>GNSS Vector Direction Analysis</h1><p>Anomaly analysis {date_format}"+"</p></header>\n<main>\n"
        linea += "<section><h2>Summary</h2>\n"

        col_f=self.sel_time.currentText()
        d1, d2 = float(d_time_j[0]), float(d_time_j[-1])
        date_in, date_fn = self._epoch_date_iso(0), self._epoch_date_iso(-1)

        file_up=self.load_file.filePath()
        linea += "<div class='step'><h3>Time series file</h3><p>"+file_up+"</p><p>\n"
        linea +=f"<p><b>Records number:</b> {len(l_dist)}<br> <b>Initial Epoch:</b> {date_in} <br> <b>Final Epoch:</b> {date_fn}</p>\n"

        linea +="<div class='step'><h3>Anomaly analysis</h3>\n"
        linea +="<p>Analysis conducted in accordance with the methodology defined by the NATO Standardization Agreement (STANAG), analysis with tests Mardia-Watson-Wheeler and Watson-Williams.</p>\n"
        linea +="<p>Outputs include:</p>\n<ul>\n"
        linea +=f"<li><b>Residual (R): </b><br>\n"
        linea += "<i>The Residual parameter is estimated using the circular (horizontal) test indicated by NATO. (Cihangir Akşit, E. 2010).</i></li>\n"
        linea +=f"<li><b>Confidence multiplier (M): </b>{m2:.5f}<br>\n".rstrip("0").rstrip(".")
        linea += "<i>M = 3.5 for large samples, corresponding to 99.78%, close to Near Certainty Error, But for small samples, this factor must be calculated according to NATO. (Cihangir Akşit, E. 2010).</i></li>\n"
        linea +=f"<li><b>Horizontal Standard Deviation: </b>{desv_sta_c:.5f}<br>"
        linea += "<i>This deviation considers a certain percentage of the error in the two axes E (X) and N (Y) of the error vectors, estimated for both components together. This represents a confidence level of 39.35% (Cihangir Akşit, E. 2010).</i></li>\n"
        linea +=f"<li><b>Threshold criteria: </b>{m2_desv:.5f}<br>\n"
        linea += "<i>A residual is considered to be an anomalies (i.e. not part of the representative data set) if the absolute value of the residual is larger than a defined value. This value equates to the standard deviation of the observation multiplied by a statistical factor, M (Cihangir Akşit, E. 2010).</i></li>\n"
        linea +=f"<li><b>Total Anomalies: </b>{sum_out:.0f}<br>\n"
        linea += "<i>The number of position variations whose apparent displacement is larger than the reference value.</i>\n</li>\n</ul>\n"
        linea += "The residual value is estimated in proportion to the days in the analyzed interval (Residual/Days)\n"

        linea +="<h3>List Anomalies</h3>\n"
        linea +="<p>Displays all detected Anomalies.</p>\n</div>\n"

        if len(list_outliers)>0:
            linea +="<div class='table-container'>\n"
