            linea += "<table border=1>\n<thead>\n<tr>\n<th></th>\n<th>Initial Epoch</th>\n<th>Final Epoch</th>\n<th>Interval (days)</th>\n<th>North component difference</th>\n<th>East component difference</th>\n<th>Residual</th>\n<th>Residual/Days</th>\n<th>Azimut</sth>\n<th>Type</th>\n</tr>\n</thead>\n<tbody>\n"
            
            cont_ano=0
