                c3=list_int[pos]
                c4=round(list_dn[pos+1],dec_n)
                c5=round(list_de[pos+1],dec_n)
                c6=round(list_residual[i],dec_n)
                c7=round(list_residual[i]/list_int[pos],dec_n)
