                if (list_residual[i]/list_int[pos])>=desv_sta_c:
                    c9="Anomaly"
                    cont_ano+=1
                else:
                    c9=""
                dist_tr=round(list_residual[i]/list_int[pos],dec_n)
                if i<5:
                    linea += f"<tr>\n<td>{c0}</td>\n<td>{c1}</td>\n<td>{c2}</td>\n<td>{c3}</td>\n<td>{c4}</td>\n<td>{c5}</td>\n<td>{c6}</td>\n"
