                    linea +=f"<i>Threshold criteria (Trend global): {self.dec_a_ggmmss(m2*dec_all)}</i><br>\n"
                    linea +=f"<i>Angular Distance (Trend global - anomalous): {self.dec_a_ggmmss(dist_anomalo_all)}</i><br>\n"
                    if dist_anomalo_all>=(m2*dec_all):
                        linea +="<i>The anomalous azimuth deviates from the global trend.</i><br>\n"
                        op=1
                    else:
                        linea +="<i>The anomalous azimuth is within the global trend.</i><br>\n"
